-- Original empty schema, extracted from Agro-Shield commit
-- 1c353807d0ad6daa4964c1b8ede8908b10a4a0b6, internal/database/database.go.
-- No production data or credentials are included. Used only in disposable tests.

CREATE TABLE IF NOT EXISTS farmers (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	full_name TEXT NOT NULL,
	phone TEXT NOT NULL UNIQUE,
	email TEXT,
	password_hash TEXT NOT NULL,
	location TEXT NOT NULL,
	lga TEXT,
	state TEXT,
	country TEXT NOT NULL,
	role TEXT NOT NULL DEFAULT 'farmer',
	photo_url TEXT NOT NULL DEFAULT '/static/assets/images/un.jpeg',
	bank_name TEXT,
	account_name TEXT,
	account_number VARCHAR(10),
	wallet_number VARCHAR(10),
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT farmers_photo_url_nonblank CHECK (BTRIM(photo_url) <> ''),
	CONSTRAINT farmers_account_number_valid CHECK (account_number IS NULL OR account_number = '' OR account_number ~ '^[0-9]{10}$'),
	CONSTRAINT farmers_wallet_number_valid CHECK (wallet_number IS NULL OR wallet_number ~ '^[0-9]{10}$')
);
CREATE INDEX IF NOT EXISTS idx_farmers_role ON farmers(role);
CREATE INDEX IF NOT EXISTS idx_farmers_state_lga ON farmers(state, lga);

ALTER TABLE farmers ADD COLUMN IF NOT EXISTS bank_code TEXT;

ALTER TABLE farmers ADD COLUMN IF NOT EXISTS wallet_number VARCHAR(10);

UPDATE farmers
		SET wallet_number = '8' || LPAD(id::text, 9, '0')
		WHERE wallet_number IS NULL OR wallet_number = '';

CREATE UNIQUE INDEX IF NOT EXISTS idx_farmers_wallet_number ON farmers(wallet_number) WHERE wallet_number IS NOT NULL;

DO $$
		BEGIN
			IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'farmers_wallet_number_valid') THEN
				ALTER TABLE farmers ADD CONSTRAINT farmers_wallet_number_valid
					CHECK (wallet_number IS NULL OR wallet_number ~ '^[0-9]{10}$');
			END IF;
		END $$;

ALTER TABLE farmers ADD COLUMN IF NOT EXISTS is_admin BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE farmers ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP;

CREATE TABLE IF NOT EXISTS crops (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	farmer_id INTEGER NOT NULL,
	name TEXT NOT NULL,
	quantity DOUBLE PRECISION NOT NULL,
	unit TEXT NOT NULL,
	location TEXT NOT NULL,
	lga TEXT,
	state TEXT,
	country TEXT NOT NULL,
	latitude DOUBLE PRECISION,
	longitude DOUBLE PRECISION,
	location_accuracy DOUBLE PRECISION,
	price_per_unit DOUBLE PRECISION NOT NULL,
	listed_for_sale BOOLEAN NOT NULL DEFAULT FALSE,
	image_url TEXT NOT NULL DEFAULT '/static/assets/images/un.jpeg',
	initial_listed_quantity DOUBLE PRECISION,
	first_listed_at TIMESTAMP,
	first_order_at TIMESTAMP,
	sold_out_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_crops_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE CASCADE,
	CONSTRAINT crops_image_url_nonblank CHECK (BTRIM(image_url) <> ''),
	CONSTRAINT chk_crops_quantity CHECK (quantity >= 0),
	CONSTRAINT chk_crops_price CHECK (price_per_unit >= 0),
	CONSTRAINT chk_crops_latitude CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
	CONSTRAINT chk_crops_longitude CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
	CONSTRAINT chk_crops_location_accuracy CHECK (location_accuracy IS NULL OR location_accuracy > 0)
);
CREATE INDEX IF NOT EXISTS idx_crops_farmer ON crops(farmer_id);
CREATE INDEX IF NOT EXISTS idx_crops_marketplace ON crops(listed_for_sale, quantity, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_crops_name ON crops(name);
CREATE INDEX IF NOT EXISTS idx_crops_location ON crops(state, lga);

CREATE TABLE IF NOT EXISTS crop_images (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	crop_id INTEGER NOT NULL,
	image_url TEXT NOT NULL,
	is_primary BOOLEAN NOT NULL DEFAULT FALSE,
	sort_order INTEGER NOT NULL DEFAULT 0,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_crop_images_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE CASCADE,
	CONSTRAINT chk_crop_images_url CHECK (BTRIM(image_url) <> '')
);
CREATE INDEX IF NOT EXISTS idx_crop_images_crop ON crop_images(crop_id, sort_order);

CREATE TABLE IF NOT EXISTS produce_price_history (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	crop_id INTEGER NOT NULL,
	price_per_unit DOUBLE PRECISION NOT NULL,
	unit TEXT NOT NULL,
	source TEXT NOT NULL DEFAULT 'Agro-Shield',
	observed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_price_history_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_price_history_crop_time ON produce_price_history(crop_id, observed_at DESC);

CREATE TABLE IF NOT EXISTS inventory_history (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	crop_id INTEGER NOT NULL,
	quantity_before DOUBLE PRECISION NOT NULL,
	quantity_change DOUBLE PRECISION NOT NULL,
	quantity_after DOUBLE PRECISION NOT NULL,
	reason TEXT NOT NULL,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_inventory_history_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_inventory_history_crop_time ON inventory_history(crop_id, created_at DESC);

CREATE TABLE IF NOT EXISTS external_market_prices (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	produce_type TEXT NOT NULL,
	price_per_unit DOUBLE PRECISION NOT NULL,
	unit TEXT NOT NULL,
	currency TEXT NOT NULL DEFAULT 'NGN',
	provider TEXT NOT NULL,
	market_name TEXT NOT NULL,
	lga TEXT,
	state TEXT,
	country TEXT NOT NULL,
	collected_at TIMESTAMP NOT NULL,
	imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	source_url TEXT
);
CREATE INDEX IF NOT EXISTS idx_external_prices_produce_market_time ON external_market_prices(produce_type, state, collected_at DESC);

CREATE TABLE IF NOT EXISTS lga_neighbors (
	state TEXT NOT NULL,
	lga TEXT NOT NULL,
	neighbor_lga TEXT NOT NULL,
	PRIMARY KEY (state, lga, neighbor_lga)
);

CREATE TABLE IF NOT EXISTS market_events (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	event_type TEXT NOT NULL,
	crop_id INTEGER,
	user_id INTEGER,
	session_id TEXT,
	metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_market_events_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE CASCADE,
	CONSTRAINT fk_market_events_user FOREIGN KEY (user_id) REFERENCES farmers(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_market_events_crop_time ON market_events(crop_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_market_events_type_time ON market_events(event_type, created_at DESC);

CREATE TABLE IF NOT EXISTS marketplace_searches (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	search_term TEXT NOT NULL,
	normalized_produce TEXT,
	location TEXT,
	user_id INTEGER,
	session_id TEXT,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_marketplace_searches_user FOREIGN KEY (user_id) REFERENCES farmers(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_marketplace_searches_term_time ON marketplace_searches(normalized_produce, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_marketplace_searches_location_time ON marketplace_searches(location, created_at DESC);

CREATE TABLE IF NOT EXISTS diagnoses (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	farmer_id INTEGER NOT NULL,
	category TEXT NOT NULL DEFAULT '',
	description TEXT NOT NULL DEFAULT '',
	result TEXT NOT NULL,
	image_name TEXT,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_diagnoses_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_diagnoses_farmer_time ON diagnoses(farmer_id, created_at DESC);

CREATE TABLE IF NOT EXISTS diagnosis_media (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	diagnosis_id INTEGER NOT NULL,
	media_type TEXT NOT NULL,
	file_name TEXT NOT NULL,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_diagnosis_media_diagnosis FOREIGN KEY (diagnosis_id) REFERENCES diagnoses(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_diagnosis_media_diagnosis ON diagnosis_media(diagnosis_id);

CREATE TABLE IF NOT EXISTS negotiations (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	crop_id INTEGER NOT NULL,
	buyer_id INTEGER NOT NULL,
	farmer_id INTEGER NOT NULL,
	quantity DOUBLE PRECISION NOT NULL,
	initial_offer_price NUMERIC(12,2) NOT NULL DEFAULT 0,
	current_offer_price NUMERIC(12,2) NOT NULL DEFAULT 0,
	round_count INTEGER NOT NULL DEFAULT 0,
	max_rounds INTEGER NOT NULL DEFAULT 5,
	status TEXT NOT NULL DEFAULT 'pending',
	expires_at TIMESTAMP,
	accepted_at TIMESTAMP,
	closed_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_negotiations_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE CASCADE,
	CONSTRAINT fk_negotiations_buyer FOREIGN KEY (buyer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_negotiations_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT chk_negotiations_quantity CHECK (quantity > 0),
	CONSTRAINT chk_negotiations_prices CHECK (initial_offer_price >= 0 AND current_offer_price >= 0),
	CONSTRAINT chk_negotiations_rounds CHECK (round_count >= 0 AND max_rounds > 0)
);
CREATE INDEX IF NOT EXISTS idx_negotiations_crop ON negotiations(crop_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_negotiations_buyer ON negotiations(buyer_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_negotiations_farmer ON negotiations(farmer_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_negotiations_status_expiry ON negotiations(status, expires_at);

CREATE TABLE IF NOT EXISTS negotiation_messages (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	negotiation_id INTEGER NOT NULL,
	sender_id INTEGER NOT NULL,
	message_type TEXT NOT NULL DEFAULT 'offer',
	offer_price DOUBLE PRECISION NOT NULL DEFAULT 0,
	message TEXT NOT NULL DEFAULT '',
	offer_status TEXT NOT NULL DEFAULT 'pending',
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_messages_negotiation FOREIGN KEY (negotiation_id) REFERENCES negotiations(id) ON DELETE CASCADE,
	CONSTRAINT fk_messages_sender FOREIGN KEY (sender_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT chk_message_type CHECK (message_type IN ('message', 'offer')),
	CONSTRAINT chk_offer_status CHECK (offer_status IN ('none', 'pending', 'accepted', 'rejected'))
);
CREATE INDEX IF NOT EXISTS idx_negotiation_messages_negotiation ON negotiation_messages(negotiation_id, created_at);

CREATE TABLE IF NOT EXISTS cart_items (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	buyer_id INTEGER NOT NULL,
	crop_id INTEGER NOT NULL,
	negotiation_id INTEGER NOT NULL,
	quantity DOUBLE PRECISION NOT NULL,
	price_per_unit DOUBLE PRECISION NOT NULL,
	total_price DOUBLE PRECISION NOT NULL,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_cart_items_buyer FOREIGN KEY (buyer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_cart_items_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE RESTRICT,
	CONSTRAINT fk_cart_items_negotiation FOREIGN KEY (negotiation_id) REFERENCES negotiations(id) ON DELETE CASCADE,
	CONSTRAINT chk_cart_items_quantity CHECK (quantity > 0),
	CONSTRAINT chk_cart_items_price CHECK (price_per_unit > 0),
	CONSTRAINT chk_cart_items_total CHECK (total_price > 0)
);
CREATE INDEX IF NOT EXISTS idx_cart_items_buyer ON cart_items(buyer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_cart_items_negotiation ON cart_items(negotiation_id);

CREATE TABLE IF NOT EXISTS orders (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	buyer_id INTEGER NOT NULL,
	crop_id INTEGER NOT NULL,
	quantity DOUBLE PRECISION NOT NULL,
	total_price DOUBLE PRECISION NOT NULL,
	status TEXT NOT NULL DEFAULT 'pending',
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_orders_buyer FOREIGN KEY (buyer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_orders_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE RESTRICT,
	CONSTRAINT chk_orders_quantity CHECK (quantity > 0),
	CONSTRAINT chk_orders_total CHECK (total_price >= 0)
);
CREATE INDEX IF NOT EXISTS idx_orders_buyer_time ON orders(buyer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_crop_time ON orders(crop_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_status_time ON orders(status, created_at DESC);

-- Idempotency for a marketplace checkout. The token is generated per rendered
-- buy form and reused if that form is submitted again, so a retried request
-- finds its earlier order instead of debiting the wallet a second time. Rows
-- created before this column existed stay NULL and are unaffected.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS checkout_token TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_checkout_token
	ON orders(checkout_token) WHERE checkout_token IS NOT NULL;

CREATE TABLE IF NOT EXISTS deliveries (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	order_id INTEGER NOT NULL,
	buyer_id INTEGER NOT NULL,
	farmer_id INTEGER NOT NULL,
	crop_id INTEGER NOT NULL,
	quantity DOUBLE PRECISION NOT NULL,
	delivery_address TEXT NOT NULL,
	lga TEXT,
	state TEXT,
	country TEXT NOT NULL,
	latitude DOUBLE PRECISION,
	longitude DOUBLE PRECISION,
	status TEXT NOT NULL DEFAULT 'pending',
	courier_name TEXT,
	courier_phone TEXT,
	tracking_number TEXT,
	vehicle_info TEXT,
	scheduled_at TIMESTAMP,
	estimated_arrival TIMESTAMP,
	picked_up_at TIMESTAMP,
	delivered_at TIMESTAMP,
	cancelled_at TIMESTAMP,
	notes TEXT,
	proof_of_delivery TEXT,
	failure_reason TEXT,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_deliveries_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
	CONSTRAINT fk_deliveries_buyer FOREIGN KEY (buyer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_deliveries_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_deliveries_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE RESTRICT,
	CONSTRAINT chk_deliveries_quantity CHECK (quantity > 0),
	CONSTRAINT chk_deliveries_status CHECK (status IN ('pending','confirmed','picked_up','in_transit','delivered','failed','cancelled'))
);
CREATE INDEX IF NOT EXISTS idx_deliveries_order ON deliveries(order_id);
CREATE INDEX IF NOT EXISTS idx_deliveries_buyer_status ON deliveries(buyer_id, status);
CREATE INDEX IF NOT EXISTS idx_deliveries_farmer_status ON deliveries(farmer_id, status);
CREATE INDEX IF NOT EXISTS idx_deliveries_status_created ON deliveries(status, created_at DESC);

CREATE TABLE IF NOT EXISTS payments (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	order_id INTEGER NOT NULL,
	reference VARCHAR(100) NOT NULL UNIQUE,
	transaction_id VARCHAR(100),
	amount NUMERIC(12,2) NOT NULL,
	currency VARCHAR(3) NOT NULL DEFAULT 'NGN',
	status VARCHAR(20) NOT NULL DEFAULT 'pending',
	provider VARCHAR(30) NOT NULL DEFAULT 'flutterwave',
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_payment_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_payments_order_id ON payments(order_id);
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);
CREATE INDEX IF NOT EXISTS idx_payments_transaction_id ON payments(transaction_id);

CREATE TABLE IF NOT EXISTS webhook_events (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	transaction_id VARCHAR(100) NOT NULL,
	event VARCHAR(50) NOT NULL,
	payload JSONB NOT NULL,
	processed_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT uq_webhook_event UNIQUE (transaction_id, event)
);

CREATE TABLE IF NOT EXISTS wallets (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	farmer_id INTEGER NOT NULL UNIQUE,
	balance NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (balance >= 0),
	currency VARCHAR(3) NOT NULL DEFAULT 'NGN',
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE RESTRICT
);
INSERT INTO wallets (farmer_id)
SELECT id FROM farmers
ON CONFLICT (farmer_id) DO NOTHING;

-- A funding attempt. The provider column records which payment vendor owns it,
-- because more than one can fund a wallet and the reference string alone must not
-- be the only way to tell them apart. provider_transaction_id is unique only
-- WITHIN a provider: two vendors are not guaranteed to avoid colliding ids, so
-- the constraint is scoped rather than global.
CREATE TABLE IF NOT EXISTS wallet_deposits (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	wallet_id BIGINT NOT NULL,
	provider VARCHAR(30) NOT NULL DEFAULT 'flutterwave',
	reference VARCHAR(100) NOT NULL UNIQUE,
	provider_transaction_id VARCHAR(100),
	amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
	currency VARCHAR(3) NOT NULL,
	verified_amount NUMERIC(12,2),
	verified_currency VARCHAR(3),
	status VARCHAR(20) NOT NULL DEFAULT 'pending'
		CHECK (status IN ('pending','processing','successful','failed','expired','reversed')),
	failure_reason TEXT,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_deposit_wallet FOREIGN KEY (wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,
	CONSTRAINT wallet_deposits_provider_txn_unique UNIQUE (provider, provider_transaction_id)
);
CREATE INDEX IF NOT EXISTS idx_wallet_deposits_wallet_time ON wallet_deposits(wallet_id, created_at DESC);

-- One permanent NGN virtual account per farmer.
--
-- The identity document used to open the account is deliberately not a column:
-- only the kind (bvn/nin) and the consent that justified sending it are
-- recorded. tx_ref is deterministic for a farmer, so a retry after an
-- ambiguous provider answer reuses the same reference instead of opening a
-- second account. account_number is required once the row is active.
CREATE TABLE IF NOT EXISTS wallet_virtual_accounts (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	farmer_id INTEGER NOT NULL UNIQUE,
	provider VARCHAR(30) NOT NULL DEFAULT 'flutterwave',
	tx_ref VARCHAR(100) NOT NULL UNIQUE,
	order_ref VARCHAR(100) NOT NULL DEFAULT '',
	provider_ref VARCHAR(100) NOT NULL DEFAULT '',
	account_number VARCHAR(20) NOT NULL DEFAULT '',
	bank_name TEXT NOT NULL DEFAULT '',
	account_name TEXT NOT NULL DEFAULT '',
	currency VARCHAR(3) NOT NULL DEFAULT 'NGN',
	status VARCHAR(20) NOT NULL DEFAULT 'pending'
		CHECK (status IN ('pending','active','failed')),
	identity_kind VARCHAR(10) NOT NULL DEFAULT ''
		CHECK (identity_kind IN ('','bvn','nin')),
	consent_version VARCHAR(40) NOT NULL DEFAULT '',
	consent_at TIMESTAMP,
	failure_reason TEXT NOT NULL DEFAULT '',
	last_checked_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_virtual_account_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT wallet_virtual_account_number_valid
		CHECK (account_number = '' OR account_number ~ '^[0-9]{10}$'),
	CONSTRAINT wallet_virtual_account_active_has_number
		CHECK (status <> 'active' OR account_number <> '')
);
CREATE INDEX IF NOT EXISTS idx_wallet_virtual_accounts_status ON wallet_virtual_accounts(status);
CREATE INDEX IF NOT EXISTS idx_wallet_virtual_accounts_check ON wallet_virtual_accounts(last_checked_at);

CREATE TABLE IF NOT EXISTS wallet_transactions (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	wallet_id BIGINT NOT NULL,
	reference VARCHAR(120) NOT NULL UNIQUE,
	type VARCHAR(30) NOT NULL CHECK (type IN ('deposit','deposit_reversal','withdrawal_reserved','withdrawal_refund','order_payment','sale_credit','transfer_out','transfer_in','transfer_refund')),
	amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_transaction_wallet FOREIGN KEY (wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_wallet_transactions_wallet_time ON wallet_transactions(wallet_id, created_at DESC);

CREATE TABLE IF NOT EXISTS wallet_withdrawals (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	wallet_id BIGINT NOT NULL,
	farmer_id INTEGER NOT NULL,
	reference VARCHAR(100) NOT NULL UNIQUE,
	provider_transfer_id VARCHAR(100) UNIQUE,
	amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
	currency VARCHAR(3) NOT NULL,
	bank_name TEXT NOT NULL,
	bank_code TEXT NOT NULL,
	account_name TEXT NOT NULL,
	account_number VARCHAR(10) NOT NULL,
	status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','paid','rejected','failed','cancelled','expired')),
	approved_by INTEGER,
	reminded_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_withdrawal_wallet FOREIGN KEY (wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_withdrawal_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_withdrawal_approver FOREIGN KEY (approved_by) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT wallet_withdrawal_account_number_valid CHECK (account_number ~ '^[0-9]{10}$')
);
CREATE INDEX IF NOT EXISTS idx_wallet_withdrawals_status_time ON wallet_withdrawals(status, created_at);
CREATE INDEX IF NOT EXISTS idx_wallet_withdrawals_wallet_time ON wallet_withdrawals(wallet_id, created_at DESC);

CREATE TABLE IF NOT EXISTS wallet_transfers (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	sender_wallet_id BIGINT NOT NULL,
	sender_id INTEGER NOT NULL,
	recipient_wallet_id BIGINT NOT NULL,
	recipient_id INTEGER NOT NULL,
	recipient_phone TEXT NOT NULL,
	reference VARCHAR(100) NOT NULL UNIQUE,
	amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
	currency VARCHAR(3) NOT NULL DEFAULT 'NGN',
	note TEXT NOT NULL DEFAULT '',
	status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed','rejected','cancelled','expired')),
	approved_by INTEGER,
	reminded_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_wallet_transfer_sender_wallet FOREIGN KEY (sender_wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_transfer_sender FOREIGN KEY (sender_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_transfer_recipient_wallet FOREIGN KEY (recipient_wallet_id) REFERENCES wallets(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_transfer_recipient FOREIGN KEY (recipient_id) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT fk_wallet_transfer_approver FOREIGN KEY (approved_by) REFERENCES farmers(id) ON DELETE RESTRICT,
	CONSTRAINT wallet_transfer_not_self CHECK (sender_id <> recipient_id)
);
CREATE INDEX IF NOT EXISTS idx_wallet_transfers_status_time ON wallet_transfers(status, created_at);
CREATE INDEX IF NOT EXISTS idx_wallet_transfers_sender_time ON wallet_transfers(sender_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wallet_transfers_recipient_time ON wallet_transfers(recipient_id, created_at DESC);

-- Commission taken from marketplace sales.
--
-- This is a ledger, not a wallet: platform money is deliberately kept out of
-- the wallets table so it can never be confused with, or spent as, a user's
-- balance. gross_amount is the buyer's full payment, amount is the fee, and
-- the seller receives gross_amount - amount.
CREATE TABLE IF NOT EXISTS platform_revenue (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	order_id INTEGER NOT NULL,
	reference VARCHAR(120) NOT NULL UNIQUE,
	gross_amount NUMERIC(12,2) NOT NULL CHECK (gross_amount > 0),
	amount NUMERIC(12,2) NOT NULL CHECK (amount > 0),
	currency VARCHAR(3) NOT NULL DEFAULT 'NGN',
	rate_percent NUMERIC(5,2) NOT NULL CHECK (rate_percent >= 0),
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_platform_revenue_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_platform_revenue_created_at ON platform_revenue(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_platform_revenue_order ON platform_revenue(order_id);

DO $$
DECLARE
	constraint_row RECORD;
BEGIN
	IF NOT EXISTS (
		SELECT 1
		FROM pg_constraint
		WHERE conrelid = 'wallet_transactions'::regclass
			AND contype = 'c'
			AND pg_get_constraintdef(oid) ILIKE '%deposit_reversal%'
	) THEN
		FOR constraint_row IN
			SELECT conname
			FROM pg_constraint
			WHERE conrelid = 'wallet_transactions'::regclass
				AND contype = 'c'
				AND pg_get_constraintdef(oid) ILIKE '%type%'
		LOOP
			EXECUTE format('ALTER TABLE wallet_transactions DROP CONSTRAINT %I', constraint_row.conname);
		END LOOP;
		ALTER TABLE wallet_transactions ADD CONSTRAINT wallet_transactions_type_check
			CHECK (type IN ('deposit','deposit_reversal','withdrawal_reserved','withdrawal_refund','order_payment','sale_credit','transfer_out','transfer_in','transfer_refund'));
	END IF;
END $$;

ALTER TABLE wallet_withdrawals ADD COLUMN IF NOT EXISTS name_check_status   TEXT NOT NULL DEFAULT '';
ALTER TABLE wallet_withdrawals ADD COLUMN IF NOT EXISTS name_check_resolved TEXT NOT NULL DEFAULT '';
ALTER TABLE wallet_withdrawals ADD COLUMN IF NOT EXISTS name_check_detail   TEXT NOT NULL DEFAULT '';
ALTER TABLE wallet_withdrawals ADD COLUMN IF NOT EXISTS name_check_at       TIMESTAMP;

ALTER TABLE wallet_withdrawals ADD COLUMN IF NOT EXISTS reminded_at TIMESTAMP;
ALTER TABLE wallet_transfers ADD COLUMN IF NOT EXISTS reminded_at TIMESTAMP;

DO $$
DECLARE
	constraint_row RECORD;
BEGIN
	IF NOT EXISTS (
		SELECT 1
		FROM pg_constraint
		WHERE conrelid = 'wallet_withdrawals'::regclass
			AND contype = 'c'
			AND pg_get_constraintdef(oid) ILIKE '%cancelled%'
	) THEN
		FOR constraint_row IN
			SELECT conrelid::regclass AS table_name, conname
			FROM pg_constraint
			WHERE conrelid IN ('wallet_deposits'::regclass, 'wallet_withdrawals'::regclass, 'wallet_transfers'::regclass)
				AND contype = 'c'
				AND pg_get_constraintdef(oid) ILIKE '%status%'
		LOOP
			EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', constraint_row.table_name, constraint_row.conname);
		END LOOP;
		ALTER TABLE wallet_deposits
			ADD CONSTRAINT wallet_deposits_status_check
			CHECK (status IN ('pending','successful','failed','expired'));
		ALTER TABLE wallet_withdrawals
			ADD CONSTRAINT wallet_withdrawals_status_check
			CHECK (status IN ('pending','processing','paid','rejected','failed','cancelled','expired'));
		ALTER TABLE wallet_transfers
			ADD CONSTRAINT wallet_transfers_status_check
			CHECK (status IN ('pending','completed','rejected','cancelled','expired'));
	END IF;
END $$;

DO $$
DECLARE
	constraint_row RECORD;
BEGIN
	IF NOT EXISTS (
		SELECT 1
		FROM pg_constraint
		WHERE conrelid = 'wallet_transactions'::regclass
			AND contype = 'c'
			AND pg_get_constraintdef(oid) ILIKE '%order_payment%'
			AND pg_get_constraintdef(oid) ILIKE '%sale_credit%'
			AND pg_get_constraintdef(oid) ILIKE '%transfer_out%'
	) THEN
		FOR constraint_row IN
			SELECT conname
			FROM pg_constraint
			WHERE conrelid = 'wallet_transactions'::regclass
				AND contype = 'c'
				AND pg_get_constraintdef(oid) ~ '\mtype\M'
		LOOP
			EXECUTE format('ALTER TABLE wallet_transactions DROP CONSTRAINT %I', constraint_row.conname);
		END LOOP;
		ALTER TABLE wallet_transactions
			ADD CONSTRAINT chk_wallet_transactions_type
			CHECK (type IN ('deposit','deposit_reversal','withdrawal_reserved','withdrawal_refund','order_payment','sale_credit','transfer_out','transfer_in','transfer_refund'));
	END IF;
END $$;

ALTER TABLE wallet_deposits ADD COLUMN IF NOT EXISTS provider VARCHAR(30) NOT NULL DEFAULT 'flutterwave';
ALTER TABLE wallet_deposits ADD COLUMN IF NOT EXISTS verified_amount NUMERIC(12,2);
ALTER TABLE wallet_deposits ADD COLUMN IF NOT EXISTS verified_currency VARCHAR(3);
ALTER TABLE wallet_deposits ADD COLUMN IF NOT EXISTS failure_reason TEXT;

DO $$
DECLARE
	constraint_row RECORD;
BEGIN
	-- Replace the global unique on provider_transaction_id with one scoped to the
	-- provider. The reference unique is deliberately left alone.
	IF NOT EXISTS (
		SELECT 1
		FROM pg_constraint
		WHERE conrelid = 'wallet_deposits'::regclass
			AND contype = 'u'
			AND conname = 'wallet_deposits_provider_txn_unique'
	) THEN
		FOR constraint_row IN
			SELECT conname
			FROM pg_constraint
			WHERE conrelid = 'wallet_deposits'::regclass
				AND contype = 'u'
				AND conname <> 'wallet_deposits_reference_key'
		LOOP
			EXECUTE format('ALTER TABLE wallet_deposits DROP CONSTRAINT %I', constraint_row.conname);
		END LOOP;
		ALTER TABLE wallet_deposits
			ADD CONSTRAINT wallet_deposits_provider_txn_unique UNIQUE (provider, provider_transaction_id);
	END IF;

	-- Widen the status CHECK to the funding lifecycle.
	IF NOT EXISTS (
		SELECT 1
		FROM pg_constraint
		WHERE conrelid = 'wallet_deposits'::regclass
			AND contype = 'c'
			AND pg_get_constraintdef(oid) ILIKE '%expired%'
			AND pg_get_constraintdef(oid) ILIKE '%reversed%'
	) THEN
		FOR constraint_row IN
			SELECT conname
			FROM pg_constraint
			WHERE conrelid = 'wallet_deposits'::regclass
				AND contype = 'c'
				AND pg_get_constraintdef(oid) ILIKE '%status%'
		LOOP
			EXECUTE format('ALTER TABLE wallet_deposits DROP CONSTRAINT %I', constraint_row.conname);
		END LOOP;
		ALTER TABLE wallet_deposits
			ADD CONSTRAINT chk_wallet_deposits_status
			CHECK (status IN ('pending','processing','successful','failed','expired','reversed'));
	END IF;
END $$;

CREATE TABLE IF NOT EXISTS notifications (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	user_id INTEGER NOT NULL,
	title TEXT NOT NULL,
	message TEXT NOT NULL,
	type TEXT NOT NULL,
	is_read BOOLEAN NOT NULL DEFAULT FALSE,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES farmers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_notifications_user_read_time ON notifications(user_id, is_read, created_at DESC);

CREATE TABLE IF NOT EXISTS conversations (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	name TEXT,
	type TEXT NOT NULL DEFAULT 'private',
	created_by INTEGER NOT NULL,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_conversations_creator FOREIGN KEY (created_by) REFERENCES farmers(id) ON DELETE CASCADE,
	CONSTRAINT chk_conversation_type CHECK (type IN ('private','group'))
);

CREATE TABLE IF NOT EXISTS conversation_members (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	conversation_id INTEGER NOT NULL,
	user_id INTEGER NOT NULL,
	joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	last_read_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_conversation_members_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
	CONSTRAINT fk_conversation_members_user FOREIGN KEY (user_id) REFERENCES farmers(id) ON DELETE CASCADE,
	CONSTRAINT unique_conversation_member UNIQUE (conversation_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_conversation_members_user ON conversation_members(user_id, conversation_id);

CREATE TABLE IF NOT EXISTS chat_messages (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	conversation_id INTEGER NOT NULL,
	sender_id INTEGER NOT NULL,
	message TEXT NOT NULL,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_chat_messages_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
	CONSTRAINT fk_chat_messages_sender FOREIGN KEY (sender_id) REFERENCES farmers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_chat_messages_conversation_time ON chat_messages(conversation_id, created_at);

CREATE TABLE IF NOT EXISTS feedback (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	user_id INTEGER NOT NULL,
	farmer_id INTEGER NOT NULL,
	product_id INTEGER,
	rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
	comment TEXT,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_feedback_user FOREIGN KEY (user_id) REFERENCES farmers(id) ON DELETE CASCADE,
	CONSTRAINT fk_feedback_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_feedback_farmer_time ON feedback(farmer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_product_time ON feedback(product_id, created_at DESC);

CREATE TABLE IF NOT EXISTS otp_codes (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	farmer_id INTEGER NOT NULL,
	phone TEXT NOT NULL,
	purpose VARCHAR(30) NOT NULL CHECK (purpose IN ('withdrawal','transfer','password_reset')),
	code_hash TEXT NOT NULL,
	attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
	expires_at TIMESTAMP NOT NULL,
	consumed_at TIMESTAMP,
	created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT fk_otp_code_farmer FOREIGN KEY (farmer_id) REFERENCES farmers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_otp_codes_lookup ON otp_codes(farmer_id, purpose, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_otp_codes_created_at ON otp_codes(created_at);

CREATE TABLE IF NOT EXISTS bank_account_lookups (
	account_number VARCHAR(10) NOT NULL,
	bank_code      TEXT NOT NULL,
	bank_name      TEXT NOT NULL DEFAULT '',
	account_name   TEXT NOT NULL DEFAULT '',
	probed_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (account_number, bank_code)
);
CREATE INDEX IF NOT EXISTS idx_bank_account_lookups_number ON bank_account_lookups(account_number);
CREATE INDEX IF NOT EXISTS idx_bank_account_lookups_probed_at ON bank_account_lookups(probed_at);

CREATE INDEX IF NOT EXISTS idx_crops_farmer_listed ON crops(farmer_id, listed_for_sale, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_crop_images_primary ON crop_images(crop_id, is_primary, sort_order);
CREATE INDEX IF NOT EXISTS idx_negotiation_messages_sender ON negotiation_messages(sender_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_buyer_status ON orders(buyer_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_deliveries_crop_status ON deliveries(crop_id, status);
